<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { api, errorMessage, unwrap, imageUrl } from '../api'
const props = defineProps({ section: String })
const route = useRoute()
const merchant = computed(() => route.path.startsWith('/merchant'))
const page = computed(() => props.section || 'dashboard')
const items = ref([]), stats = ref(null), billing = ref(null), error = ref(''), message = ref(''), modal = ref(false), editing = ref(null), picture = ref(null)
const form = reactive({ username:'',email:'',password:'',phone:'',role:'user',name:'',category:'food',target_species:'both',description:'',price:0,stock:0,is_active:true })
const adminTabs = [['dashboard','概览'],['users','用户管理'],['pets','宠物管理'],['merchants','商户审核']]
const merchantTabs = [['products','我的商品'],['orders','商户订单'],['billing','租金账单']]
async function load() { error.value=''; try {
  if (merchant.value) { if (page.value === 'billing') billing.value = (await api.get('/merchant/billing')).data; else items.value = page.value === 'orders' ? (await api.get('/shop/merchant/orders')).data.items || [] : (await api.get('/shop/merchant/products')).data.items || [] }
  else if (page.value === 'dashboard') stats.value = (await api.get('/admin/stats')).data
  else { const url = page.value === 'users' ? '/admin/users' : `/admin/${page.value}/list`; const data = (await api.get(url)).data; items.value = data[page.value] || [] }
} catch(e) { error.value=errorMessage(e) } }
onMounted(load); watch([page,merchant],load)
function open(item=null) { editing.value=item; picture.value=null; Object.assign(form,{username:'',email:'',password:'',phone:'',role:'user',name:'',category:'food',target_species:'both',description:'',price:0,stock:0,is_active:true},item||{});modal.value=true }
async function save() { error.value=''; try {
  if (merchant.value) { const payload={name:form.name,category:form.category,target_species:form.target_species,description:form.description,price:Number(form.price),stock:Number(form.stock),is_active:form.is_active}; const data=unwrap(editing.value ? await api.put(`/shop/products/${editing.value.id}`,payload) : await api.post('/shop/products',payload)); const productId=data.product?.id || editing.value?.id; if(picture.value && productId){const body=new FormData();body.append('image',picture.value);unwrap(await api.post(`/shop/products/${productId}/image`,body))} }
  else { const payload={username:form.username,email:form.email,phone:form.phone,role:form.role,password:form.password||null}; unwrap(editing.value ? await api.put(`/admin/users/${editing.value.id}`,payload) : await api.post('/admin/users',payload)) }
  modal.value=false;message.value='已保存';await load()
} catch(e) { error.value=errorMessage(e) } }
async function remove(item) { if(!confirm(`确定删除${merchant.value?'商品':'记录'}“${item.name||item.username}”吗？`))return; try { unwrap(await api.delete(merchant.value?`/shop/products/${item.id}`:`/admin/${page.value}/${item.id}`));await load() } catch(e){error.value=errorMessage(e)} }
async function approve(item) { try { unwrap(await api.post(`/admin/merchants/${item.id}/approve`));message.value='商户已通过审核';await load() }catch(e){error.value=errorMessage(e)} }
async function status(item,value) { try { unwrap(await api.put(`/shop/orders/${item.id}/status`,{status:value}));await load() }catch(e){error.value=errorMessage(e)} }
</script>
<template>
  <div class="page-head"><div><h1>{{ merchant ? '商户中心' : '管理后台' }}</h1><p>{{ merchant ? '管理店铺商品与顾客订单' : '查看系统概况，管理用户与宠物档案' }}</p></div><button v-if="page === 'users' || (merchant && page === 'products')" class="btn" @click="open()">＋ {{ merchant ? '新增商品' : '新增用户' }}</button></div>
  <div class="tabs"><RouterLink v-for="[key,title] in merchant ? merchantTabs : adminTabs" :key="key" :to="`${merchant?'/merchant':'/admin'}/${key}`">{{ title }}</RouterLink></div>
  <div v-if="error" class="message error">{{ error }}</div><div v-if="message" class="message">{{ message }}</div>
  <div v-if="!merchant && page === 'dashboard' && stats" class="grid"><div v-for="[label,value] in [['用户数',stats.user_count],['宠物数',stats.pet_count],['健康记录',stats.health_record_count],['商户数',stats.merchant_count],['商品数',stats.product_count],['订单数',stats.order_count],['AI 分析',stats.ai_analyses]]" :key="label" class="card"><div class="muted">{{ label }}</div><div class="stat">{{ value }}</div></div></div>
  <div v-else-if="merchant && page === 'billing' && billing"><div class="three-col"><div class="card"><div class="muted">月租金</div><div class="stat">¥{{ billing.merchant.rent_amount || 0 }}</div></div><div class="card"><div class="muted">每月缴费日</div><div class="stat">{{ billing.merchant.rent_due_day || 1 }} 日</div></div><div class="card"><div class="muted">上次缴费</div><div>{{ billing.merchant.last_rent_paid?.slice(0,10) || '暂无记录' }}</div></div></div><div class="card" style="margin-top:20px"><h3>缴费记录</h3><div v-for="record in billing.rental_records" :key="record.id" class="list-row"><div><strong>¥{{ record.amount }}</strong><div class="small muted">{{ record.period_start }} 至 {{ record.period_end }} · {{ record.payment_method_display }}</div></div><span class="small muted">{{ record.paid_at?.slice(0,16) }}</span></div><div v-if="!billing.rental_records?.length" class="muted">暂无缴费记录。</div><p class="warning">线上支付尚未接入。如需缴费，请联系平台管理员确认方式。</p></div></div>
  <div v-else-if="items.length" class="card table-wrap"><table class="data-table"><thead><tr v-if="page === 'users'"><th>用户名</th><th>邮箱</th><th>角色</th><th>电话</th><th>操作</th></tr><tr v-else-if="page === 'pets'"><th>宠物</th><th>种类</th><th>主人</th><th>操作</th></tr><tr v-else-if="page === 'merchants'"><th>商户</th><th>店铺</th><th>邮箱</th><th>审核状态</th><th>操作</th></tr><tr v-else-if="page === 'products'"><th>商品</th><th>分类</th><th>价格</th><th>库存</th><th>状态</th><th>操作</th></tr><tr v-else><th>订单</th><th>顾客</th><th>本店金额</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><template v-if="page === 'users'"><td>{{ item.username }}</td><td>{{ item.email }}</td><td>{{ item.role }}</td><td>{{ item.phone }}</td><td><div class="actions"><button class="btn secondary" @click="open(item)">编辑</button><button class="btn danger" @click="remove(item)">删除</button></div></td></template><template v-else-if="page === 'pets'"><td>{{ item.name }}</td><td>{{ item.species === 'cat'?'猫':'狗' }}</td><td>{{ item.owner_name }}</td><td><button class="btn danger" @click="remove(item)">删除</button></td></template><template v-else-if="page === 'merchants'"><td>{{ item.username }}</td><td>{{ item.store_name }}</td><td>{{ item.email }}</td><td>{{ item.is_approved ? '已通过' : '待审核' }}</td><td><button v-if="!item.is_approved" class="btn" @click="approve(item)">审核通过</button></td></template><template v-else-if="page === 'products'"><td><img v-if="item.image" :src="imageUrl(item.image)" :alt="item.name" style="width:38px;height:38px;object-fit:cover;vertical-align:middle;border-radius:7px"> {{ item.name }}</td><td>{{ item.category_display }}</td><td>¥{{ item.price }}</td><td>{{ item.stock }}</td><td>{{ item.is_active?'上架':'下架' }}</td><td><div class="actions"><button class="btn secondary" @click="open(item)">编辑</button><button class="btn danger" @click="remove(item)">删除</button></div></td></template><template v-else><td>#{{ item.id }} <small class="muted">{{ item.created_at?.slice(0,10) }}</small><div v-for="product in item.items" :key="product.id" class="small">{{ product.product_name }} × {{ product.quantity }}</div></td><td>{{ item.username }}</td><td>¥{{ item.total_amount }}</td><td>{{ item.status_display }}</td><td><div class="actions"><button v-if="item.can_update_status && item.status === 'paid'" class="btn secondary" @click="status(item,'shipped')">标记已发货</button><button v-if="item.can_update_status && item.status === 'shipped'" class="btn secondary" @click="status(item,'delivered')">标记已完成</button><span v-if="!item.can_update_status" class="muted small">混合商户订单由管理员处理</span></div></td></template></tr></tbody></table></div><div v-else-if="page !== 'dashboard'" class="empty">暂无{{ merchant ? '店铺' : '管理' }}数据。</div>
  <div v-if="modal" class="modal-backdrop" @click.self="modal=false"><form class="modal" @submit.prevent="save"><div class="page-head"><h2>{{ editing?'编辑':'新增' }}{{ merchant?'商品':'用户' }}</h2><button type="button" class="text-button" @click="modal=false">关闭 ✕</button></div><div v-if="merchant" class="form-grid"><label class="field"><span>商品名称</span><input v-model.trim="form.name" required></label><label class="field"><span>分类</span><select v-model="form.category"><option value="food">宠物食品</option><option value="toy">宠物玩具</option><option value="accessory">用品配件</option><option value="medicine">健康护理</option><option value="other">其他</option></select></label><label class="field"><span>适用宠物</span><select v-model="form.target_species"><option value="both">猫狗通用</option><option value="dog">狗狗</option><option value="cat">猫咪</option></select></label><label class="field"><span>价格</span><input v-model.number="form.price" type="number" min="0" step="0.01" required></label><label class="field"><span>库存</span><input v-model.number="form.stock" type="number" min="0" step="1" required></label><label class="field"><span>状态</span><select v-model="form.is_active"><option :value="true">上架</option><option :value="false">下架</option></select></label><label class="field full"><span>商品介绍</span><textarea v-model="form.description"></textarea></label><label class="field full"><span>商品图片</span><input type="file" accept="image/*" @change="picture=$event.target.files[0]"></label></div><div v-else class="form-grid"><label class="field"><span>用户名</span><input v-model.trim="form.username" minlength="3" required></label><label class="field"><span>邮箱</span><input v-model.trim="form.email" type="email" required></label><label class="field"><span>电话</span><input v-model.trim="form.phone"></label><label class="field"><span>角色</span><select v-model="form.role"><option value="user">普通用户</option><option value="merchant">商户</option><option value="admin">管理员</option></select></label><label class="field full"><span>密码{{ editing?'（留空则保持不变）':'' }}</span><input v-model="form.password" type="password" :required="!editing" :minlength="form.password?6:undefined"></label></div><div class="actions"><button class="btn">保存</button></div></form></div>
</template>
